import io
import subprocess
import sys
from pathlib import Path

import pytest

from kebab import main, slugify

SCRIPT = Path(__file__).resolve().parent.parent / "src" / "kebab.py"


def test_lowercases_and_joins_words_with_hyphens():
    assert slugify("Hello World") == "hello-world"


def test_collapses_punctuation_and_whitespace_runs():
    assert slugify("Hello,   World!!  How are\tyou?") == "hello-world-how-are-you"


def test_strips_leading_and_trailing_separators():
    assert slugify("  --Hello World--  ") == "hello-world"


@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("Café au lait", "cafe-au-lait"),
        ("Crème Brûlée", "creme-brulee"),
        ("Straße", "strasse"),
        ("Ångström", "angstrom"),
    ],
)
def test_transliterates_accented_letters_to_ascii(text, expected):
    assert slugify(text) == expected


def test_drops_apostrophes_instead_of_splitting_words():
    assert slugify("Don't Stop Believin’") == "dont-stop-believin"


def test_keeps_digits():
    assert slugify("Top 10 Python Tips 2026") == "top-10-python-tips-2026"


def test_converts_underscores_and_camel_free_identifiers():
    assert slugify("snake_case_name") == "snake-case-name"


@pytest.mark.parametrize("text", ["", "   ", "!!! ??? ...", "日本語"])
def test_returns_empty_string_when_nothing_sluggable(text):
    assert slugify(text) == ""


def test_custom_separator():
    assert slugify("Hello World Again", separator="_") == "hello_world_again"


def test_cli_joins_arguments_into_one_slug(capsys):
    assert main(["Hello", "World!"]) == 0
    assert capsys.readouterr().out == "hello-world\n"


def test_cli_separator_option(capsys):
    assert main(["--separator", "_", "Hello World"]) == 0
    assert capsys.readouterr().out == "hello_world\n"


def test_cli_reads_stdin_line_by_line(capsys, monkeypatch):
    monkeypatch.setattr(sys, "stdin", io.StringIO("First Post\nSecond Post!\n"))
    assert main([]) == 0
    assert capsys.readouterr().out == "first-post\nsecond-post\n"


def test_script_runs_as_a_standalone_command():
    result = subprocess.run(
        [sys.executable, str(SCRIPT), "Ünïcödé", "Rocks"],
        capture_output=True,
        text=True,
        check=True,
    )
    assert result.stdout == "unicode-rocks\n"
